#!/usr/bin/env python3
"""Writes data/glossary.json: the master glossary (term, category, meaning).
Daily lessons add their own terms on top; the page merges both."""
import json, os

C, J, S, D, A, I, L = "Coding", "Java", "Spring", "System design", "AI", "Interview", "LLD & patterns"
T = [
# ---------- Coding: complexity and basics ----------
("Algorithm", C, "A step-by-step recipe for solving a problem."),
("Data structure", C, "A way of organising data in memory so certain operations are fast, e.g. an array, a hash map or a tree."),
("Big-O", C, "Describes how an algorithm's time or memory grows as the input grows, ignoring constants. O(n) means it grows in a straight line with the input."),
("Time complexity", C, "How the number of steps an algorithm takes grows with the input size."),
("Space complexity", C, "How much extra memory an algorithm needs as the input grows, not counting the input itself."),
("O(1)", C, "Constant time: the cost does not change with input size, e.g. reading array[5]."),
("O(log n)", C, "Logarithmic time: each step halves the work, e.g. binary search. A million items take about 20 steps."),
("O(n)", C, "Linear time: you look at each element a fixed number of times."),
("O(n log n)", C, "The cost of efficient sorting such as merge sort or Java's Arrays.sort for objects."),
("O(n²)", C, "Quadratic time: comparing every element with every other. Too slow for large inputs (about 100,000+)."),
("Amortized complexity", C, "The average cost per operation over a long sequence. ArrayList.add is O(1) amortized even though an occasional resize is O(n)."),
("Brute force", C, "The simplest correct solution, usually trying every possibility. Say it first in interviews, then improve it."),
("Edge case", C, "An unusual input that often breaks code: empty input, one element, duplicates, negatives, very large values."),
("Dry run", C, "Walking through your code by hand with a small example to check it works."),
("In-place", C, "Changing the input directly without allocating extra space proportional to n."),
("Pattern", C, "A reusable approach that solves a family of problems, e.g. two pointers or sliding window."),
("Array", C, "A fixed-size block of elements stored next to each other in memory; reading by index is O(1)."),
("Dynamic array", C, "An array that grows automatically when full, like Java's ArrayList."),
("String", C, "A sequence of characters. In Java, String objects are immutable."),
("Hash function", C, "Turns a key into a number that decides which bucket the key goes into."),
("Hash map", C, "Stores key-value pairs with O(1) average lookup, insert and delete. Java: HashMap."),
("Hash set", C, "Stores unique values with O(1) average 'is it here?' checks. Java: HashSet."),
("Collision", C, "When two different keys hash to the same bucket. Handled by chaining (a list or tree per bucket)."),
("Frequency map", C, "A map from each value to how many times it appears, e.g. counting characters in a string."),
("Prefix sum", C, "An array where each position holds the total of all elements before it, so any range sum is O(1)."),
("Running total", C, "A sum that you update as you move through the data, the idea behind prefix sums."),
("Two pointers", C, "Using two indexes that move through the data (often from both ends) to avoid nested loops."),
("Sliding window", C, "A range [left, right] that grows and shrinks as you scan, used for subarray and substring problems."),
("Fixed window", C, "A sliding window that always has the same size k."),
("Variable window", C, "A sliding window whose size changes: expand on the right, shrink on the left when a rule breaks."),
("Stack", C, "Last in, first out. Push adds to the top, pop removes from the top. Java: ArrayDeque."),
("Queue", C, "First in, first out. Offer adds to the back, poll removes from the front. Java: ArrayDeque or LinkedList."),
("Deque", C, "Double-ended queue: add or remove at both ends in O(1)."),
("Monotonic stack", C, "A stack kept in increasing or decreasing order, used to find the next greater or smaller element in O(n)."),
("Monotonic queue", C, "A deque kept in order, used for sliding-window maximum or minimum."),
("Binary search", C, "Finds a target in sorted data by halving the search range each step: O(log n)."),
("Binary search on the answer", C, "Binary searching over possible answers (e.g. a speed or capacity) using a yes/no feasibility check."),
("lo / hi / mid", C, "The left bound, right bound and middle index in binary search. Compute mid as lo + (hi - lo) / 2 to avoid overflow."),
("Off-by-one error", C, "A bug where a loop or index is one too many or one too few, common in binary search."),
("Rotated sorted array", C, "A sorted array shifted around a pivot, e.g. [4,5,6,1,2,3]."),
("Linked list", C, "Nodes where each points to the next. Insert/delete is O(1) at a known node; access by index is O(n)."),
("Doubly linked list", C, "A linked list whose nodes point both forward and backward."),
("Dummy head", C, "A fake first node that removes special cases when building or editing a linked list."),
("Fast and slow pointers", C, "Two pointers moving at different speeds, used to find the middle of a list or detect a cycle."),
("Floyd's cycle detection", C, "The tortoise-and-hare method: if a fast pointer meets a slow one, the list has a cycle."),
("LRU cache", C, "Least Recently Used cache: evicts the item unused for the longest time. Built with a hash map + doubly linked list."),
("Tree", C, "A hierarchy of nodes with one root and no cycles."),
("Binary tree", C, "A tree where each node has at most two children: left and right."),
("Root / leaf", C, "The root is the top node; a leaf has no children."),
("Height / depth", C, "Height: longest path from a node down to a leaf. Depth: distance from the root down to a node."),
("Balanced tree", C, "A tree where the heights of the left and right subtrees differ by at most one at every node."),
("Binary search tree (BST)", C, "A binary tree where left < node < right everywhere, so an in-order walk is sorted."),
("Recursion", C, "A function that calls itself on a smaller version of the problem until it reaches a base case."),
("Base case", C, "The simplest input where a recursive function stops calling itself."),
("Call stack", C, "Memory that tracks active function calls. Very deep recursion can overflow it (StackOverflowError)."),
("DFS (depth-first search)", C, "Explores as far as possible along one branch before backtracking. Uses recursion or a stack."),
("BFS (breadth-first search)", C, "Explores level by level using a queue. Finds shortest paths in unweighted graphs."),
("Pre-order / in-order / post-order", C, "Orders of visiting tree nodes: node first, node in the middle, or node last."),
("Level-order traversal", C, "Visiting a tree level by level, i.e. BFS on a tree."),
("Lowest common ancestor (LCA)", C, "The deepest node that has both given nodes as descendants."),
("Serialization", C, "Turning a data structure into a string or bytes so it can be stored or sent, and rebuilt later."),
("Heap", C, "A tree-shaped structure where the smallest (min-heap) or largest (max-heap) item is always on top. Insert/remove O(log n)."),
("Priority queue", C, "A queue that always gives the highest-priority item next. Java: PriorityQueue (a min-heap by default)."),
("Top-K", C, "Finding the k largest or most frequent items, usually with a heap of size k: O(n log k)."),
("Two heaps", C, "A max-heap for the lower half and a min-heap for the upper half, used to track a running median."),
("Trie", C, "A prefix tree storing strings character by character; fast prefix search and autocomplete."),
("Interval", C, "A range with a start and an end, e.g. a meeting [9, 10]."),
("Merge intervals", C, "Sort by start, then combine ranges that overlap."),
("Backtracking", C, "Building a solution step by step and undoing (un-choosing) steps that lead to dead ends."),
("Pruning", C, "Skipping branches of a search early because they cannot lead to a valid answer."),
("Subset / permutation / combination", C, "Subset: any selection. Permutation: an ordering. Combination: a selection where order doesn't matter."),
("Graph", C, "Nodes (vertices) connected by edges. Can be directed or undirected, weighted or unweighted."),
("Adjacency list", C, "A graph stored as a map from each node to its list of neighbours."),
("Grid as a graph", C, "Treating each cell of a 2D grid as a node connected to its 4 neighbours."),
("Visited set", C, "Tracks nodes already explored so a graph search does not loop forever."),
("Multi-source BFS", C, "BFS that starts from many nodes at once, e.g. all rotten oranges spreading together."),
("Topological sort", C, "Ordering tasks so each comes after the ones it depends on. Only possible with no cycles."),
("Kahn's algorithm", C, "Topological sort using in-degrees: repeatedly take nodes with no remaining dependencies."),
("In-degree", C, "The number of edges pointing into a node."),
("DAG", C, "Directed acyclic graph: directed edges and no cycles. Airflow pipelines are DAGs."),
("Union-find", C, "Also called disjoint set union: tracks which items are connected, with near O(1) union and find."),
("Path compression", C, "A union-find speed-up that points nodes directly at their root."),
("Dijkstra's algorithm", C, "Finds shortest paths in a graph with non-negative weights using a priority queue."),
("Minimum spanning tree (MST)", C, "The cheapest set of edges that connects all nodes, found with Prim's or Kruskal's algorithm."),
("Dynamic programming (DP)", C, "Solving a problem by combining answers to overlapping smaller subproblems and storing them."),
("Memoization", C, "Top-down DP: cache results of recursive calls so each subproblem is solved once."),
("Tabulation", C, "Bottom-up DP: fill a table from the smallest subproblems upward."),
("State and transition", C, "In DP, the state is what a subproblem means (e.g. dp[i]); the transition is how it is built from smaller states."),
("Knapsack", C, "A DP family: choose items with weights and values to maximise value under a capacity limit."),
("Kadane's algorithm", C, "Finds the maximum-sum subarray in O(n) by tracking the best sum ending at each position."),
("Greedy algorithm", C, "Makes the locally best choice at each step. Works only when you can argue that choice is always safe."),
("Bit manipulation", C, "Using operators like &, |, ^ and shifts on binary numbers. x ^ x = 0 is a common trick."),
("Matrix", C, "A 2D grid of values, e.g. int[][] in Java."),
("Window function (SQL)", C, "A SQL function such as RANK() or ROW_NUMBER() that computes over a group of rows without collapsing them."),
("JOIN (SQL)", C, "Combines rows from two tables on a matching column (INNER, LEFT, RIGHT, FULL)."),
("GROUP BY (SQL)", C, "Groups rows that share values so you can aggregate them with COUNT, SUM, MAX and so on."),
# ---------- Java ----------
("JVM", J, "Java Virtual Machine: loads bytecode, manages memory and garbage collection, and runs your program."),
("JRE", J, "Java Runtime Environment: the JVM plus standard libraries; enough to run Java programs."),
("JDK", J, "Java Development Kit: the JRE plus tools to build Java (javac, jshell, jcmd, jstack)."),
("Bytecode", J, "The portable instructions javac produces (.class files), run by any JVM."),
("javac", J, "The Java compiler that turns .java source files into .class bytecode."),
("JIT compiler", J, "Just-In-Time compiler: turns frequently run bytecode into fast machine code while the program runs."),
("C1 / C2 compilers", J, "HotSpot's two JIT compilers: C1 compiles quickly; C2 takes longer and produces highly optimised code."),
("Warm-up", J, "The first minutes after a Java service starts, when it is slower because classes are loading and code is not yet JIT-compiled."),
("Class loader", J, "The part of the JVM that finds and loads classes, lazily, the first time they are used."),
("Parent delegation", J, "A class loader first asks its parent to load a class, so core classes cannot be replaced."),
("Heap (JVM)", J, "The JVM memory area where all objects live; shared by all threads and cleaned by the garbage collector."),
("Stack (JVM)", J, "Per-thread memory holding method calls, local variables and references; freed when a method returns."),
("Metaspace", J, "Native memory where the JVM stores class metadata (replaced PermGen in Java 8)."),
("Primitive type", J, "A basic value type like int, long, double or boolean, stored directly rather than as an object."),
("Wrapper class", J, "The object version of a primitive: Integer for int, Long for long, and so on."),
("Autoboxing", J, "Java automatically converting between a primitive and its wrapper, e.g. int to Integer."),
("Integer cache", J, "Java reuses Integer objects for -128 to 127, which is why == sometimes seems to work for Integers. Always use equals()."),
("Reference", J, "A variable that points to an object on the heap rather than holding the object itself."),
("Immutability", J, "An object whose state cannot change after creation, e.g. String. Immutable objects are thread-safe."),
("String pool", J, "A JVM area where string literals are stored once and reused."),
("StringBuilder", J, "A mutable string buffer for building strings efficiently in loops."),
("Class / object", J, "A class is a blueprint; an object is one instance created from it."),
("Encapsulation", J, "Hiding an object's internal state behind methods, usually with private fields."),
("Inheritance", J, "A class reusing and extending another class with extends."),
("Polymorphism", J, "One interface, many implementations: the right method is chosen at runtime based on the actual object."),
("Abstraction", J, "Exposing what something does while hiding how it does it."),
("Interface", J, "A contract of methods a class promises to implement; can have default methods since Java 8."),
("Abstract class", J, "A class that cannot be instantiated and may contain both implemented and abstract methods."),
("Composition over inheritance", J, "Building behaviour by holding other objects instead of extending classes; more flexible."),
("Method overloading / overriding", J, "Overloading: same name, different parameters (compile time). Overriding: subclass replaces a parent method (runtime)."),
("Access modifiers", J, "public, protected, package-private and private: who can see a class member."),
("static", J, "Belongs to the class rather than to any one object."),
("final", J, "Cannot be changed: a final variable cannot be reassigned, a final method cannot be overridden, a final class cannot be extended."),
("equals() and hashCode() contract", J, "If two objects are equal, they must have the same hashCode. Breaking this makes HashMap and HashSet misbehave."),
("Comparable vs Comparator", J, "Comparable defines an object's natural order (compareTo); Comparator is a separate ordering you pass in."),
("Collections framework", J, "Java's standard data structures: List, Set, Map, Queue and their implementations."),
("ArrayList", J, "A resizable array; O(1) get by index, O(n) insert in the middle."),
("LinkedList (Java)", J, "A doubly linked list; also usable as a queue. Slow random access."),
("HashMap", J, "Java's hash table. Not thread-safe. Average O(1) get and put."),
("Load factor", J, "How full a HashMap can get before it resizes; 0.75 by default."),
("Rehashing", J, "Resizing a hash table and moving every entry to its new bucket."),
("Treeification", J, "Since Java 8, a HashMap bucket with many entries becomes a red-black tree, so the worst case is O(log n)."),
("TreeMap", J, "A sorted map backed by a red-black tree; O(log n) operations and ordered keys."),
("LinkedHashMap", J, "A HashMap that remembers insertion or access order; easy base for an LRU cache."),
("ArrayDeque", J, "A fast resizable double-ended queue; the recommended stack and queue in Java."),
("PriorityQueue", J, "Java's heap; a min-heap by default. Pass Collections.reverseOrder() for a max-heap."),
("Fail-fast iterator", J, "Throws ConcurrentModificationException if a collection is changed while being iterated."),
("Generics", J, "Type parameters like List<String> that give compile-time type safety."),
("Type erasure", J, "Generic types are removed at compile time, so at runtime List<String> and List<Integer> are the same class."),
("Wildcards / PECS", J, "? extends T and ? super T. PECS: Producer Extends, Consumer Super."),
("Checked exception", J, "An exception the compiler forces you to handle or declare, e.g. IOException."),
("Unchecked exception", J, "A RuntimeException the compiler does not force you to handle, e.g. NullPointerException."),
("try-with-resources", J, "A try block that closes resources such as streams and connections automatically."),
("Lambda", J, "A short anonymous function, e.g. x -> x * 2."),
("Functional interface", J, "An interface with a single abstract method, which a lambda can implement (Runnable, Function, Predicate)."),
("Stream API", J, "A pipeline for processing collections: filter, map, reduce, collect."),
("Lazy evaluation (streams)", J, "Stream steps don't run until a terminal operation like collect() is called."),
("Optional", J, "A container that may or may not hold a value; makes 'no result' explicit instead of returning null."),
("Record", J, "A concise immutable data class (Java 16+) with auto-generated constructor, equals, hashCode and toString."),
("Sealed class", J, "A class that restricts which classes may extend it (Java 17+)."),
("Garbage collection (GC)", J, "The JVM automatically freeing memory used by objects that are no longer reachable."),
("Young / old generation", J, "Heap areas: new objects start young; objects that survive several collections move to old."),
("Minor / major GC", J, "Minor GC cleans the young generation (fast); major or full GC cleans the old generation (slower)."),
("Stop-the-world pause", J, "A moment when the JVM pauses all application threads to do GC work."),
("G1 GC", J, "The default garbage collector since Java 9; splits the heap into regions and targets predictable pauses."),
("ZGC", J, "A low-latency garbage collector with very short pauses, even on large heaps."),
("Memory leak (Java)", J, "Objects that are still referenced but never used again, so GC cannot free them."),
("OutOfMemoryError", J, "Thrown when the JVM cannot allocate memory; the message says which area ran out (heap, metaspace and so on)."),
("Heap dump", J, "A snapshot of all objects in memory, used to find leaks."),
("Thread dump", J, "A snapshot of what every thread is doing, used to find deadlocks and stuck threads (jstack)."),
("Thread", J, "An independent path of execution inside a program."),
("Runnable vs Callable", J, "Runnable returns nothing; Callable returns a value and can throw checked exceptions."),
("Race condition", J, "A bug where the result depends on the timing of threads, e.g. two threads incrementing a counter."),
("Critical section", J, "Code that must not be run by more than one thread at a time."),
("synchronized", J, "A keyword that lets only one thread at a time run a block or method on a given lock."),
("Monitor / intrinsic lock", J, "The lock every Java object has, used by synchronized."),
("volatile", J, "Makes writes to a variable immediately visible to other threads; does not make compound actions atomic."),
("Java Memory Model (JMM)", J, "The rules for when one thread's writes become visible to another."),
("Happens-before", J, "A JMM guarantee that one action's effects are visible to another, e.g. unlocking before the next lock."),
("Deadlock", J, "Two or more threads each waiting forever for a lock the other holds."),
("Livelock / starvation", J, "Livelock: threads keep reacting to each other and make no progress. Starvation: a thread never gets a turn."),
("ExecutorService", J, "Java's thread pool API: submit tasks instead of creating threads yourself."),
("Thread pool", J, "A fixed group of reusable threads that run submitted tasks."),
("ReentrantLock", J, "An explicit lock with extra features over synchronized: tryLock, timeouts, fairness."),
("ReadWriteLock", J, "Lets many readers share access but gives writers exclusive access."),
("ConcurrentHashMap", J, "A thread-safe HashMap that locks only small parts of the map, so many threads can work at once."),
("BlockingQueue", J, "A thread-safe queue where take() waits for an item and put() waits for space; the basis of producer-consumer."),
("CompletableFuture", J, "Represents an async result you can chain (thenApply, thenCombine) and handle errors on."),
("Atomic variables / CAS", J, "AtomicInteger and friends update values safely without locks using compare-and-swap."),
("Producer-consumer", J, "One set of threads produces work into a queue; another consumes it."),
("Virtual threads", J, "Lightweight threads (Java 21) managed by the JVM, so you can run millions of blocking tasks cheaply."),
("Singleton", L, "A design pattern ensuring a class has only one instance."),
# ---------- Spring ----------
("Spring Framework", S, "A Java framework that manages your objects (beans) and wires them together."),
("Spring Boot", S, "Spring with sensible defaults and auto-configuration so a production service starts with little setup."),
("IoC (Inversion of Control)", S, "The framework creates and connects your objects instead of your code doing it."),
("Dependency injection (DI)", S, "Objects receive the things they need (dependencies) from outside, usually through the constructor."),
("Bean", S, "An object created and managed by the Spring container."),
("Application context", S, "Spring's container that holds and wires all the beans."),
("Bean scope", S, "How many instances Spring creates: singleton (one, the default), prototype (new each time), request, session."),
("Bean lifecycle", S, "Creation, dependency injection, initialisation (@PostConstruct) and destruction (@PreDestroy) of a bean."),
("Auto-configuration", S, "Spring Boot configures beans automatically based on what is on the classpath."),
("Starter", S, "A Spring Boot dependency bundle such as spring-boot-starter-web."),
("Profile", S, "A named set of configuration (dev, test, prod) switched on with spring.profiles.active."),
("@RestController", S, "Marks a class whose methods handle HTTP requests and return JSON."),
("DispatcherServlet", S, "The front controller in Spring MVC that routes each HTTP request to the right controller method."),
("Filter vs interceptor", S, "Filters run in the servlet layer before Spring; interceptors run inside Spring MVC around controllers."),
("@ControllerAdvice", S, "A class that handles exceptions globally for all controllers."),
("JPA", S, "Java Persistence API: a standard way to map Java objects to database tables."),
("Hibernate", S, "The most common JPA implementation."),
("Entity", S, "A Java class mapped to a database table with @Entity."),
("Persistence context", S, "Hibernate's in-memory cache of entities loaded in the current transaction."),
("Lazy vs eager loading", S, "Lazy loads related data only when accessed; eager loads it immediately."),
("N+1 query problem", S, "Loading a list then firing one extra query per item. Fix with JOIN FETCH, entity graphs or batching."),
("@Transactional", S, "Runs a method inside a database transaction; commits on success and rolls back on runtime exceptions."),
("Propagation", S, "What @Transactional does when a transaction already exists: join it (REQUIRED), start a new one (REQUIRES_NEW) and so on."),
("Isolation level", S, "How much one transaction can see of others' uncommitted work: READ_COMMITTED, REPEATABLE_READ, SERIALIZABLE."),
("AOP", S, "Aspect-Oriented Programming: adds behaviour such as transactions, logging or security around methods without changing them."),
("Proxy", S, "A wrapper object Spring creates around a bean to add behaviour. Self-calls inside a class bypass it."),
("Spring Security", S, "Spring's framework for authentication and authorisation, built as a chain of filters."),
("JWT", S, "JSON Web Token: a signed token carrying a user's identity and claims, sent with each request."),
("OAuth2", S, "A standard for letting an app access resources on a user's behalf using tokens instead of passwords."),
("Spring Kafka", S, "Spring's integration for producing and consuming Kafka messages with @KafkaListener."),
("Dead-letter topic (DLT)", S, "A Kafka topic where messages that keep failing are parked for later inspection."),
("@Cacheable", S, "Caches a method's result so repeat calls with the same arguments skip the work."),
("Resilience4j", S, "A library for circuit breakers, retries, rate limiters and timeouts in Java services."),
("Actuator", S, "Spring Boot endpoints for health, metrics and info about a running service."),
("Micrometer", S, "A metrics library used by Spring Boot to export metrics to tools like Prometheus or Datadog."),
("JUnit / Mockito", S, "JUnit runs Java tests; Mockito creates fake dependencies (mocks) for unit tests."),
("Testcontainers", S, "Runs real databases or Kafka in Docker containers during tests."),
# ---------- Low-level design ----------
("SOLID", L, "Five design principles: Single responsibility, Open/closed, Liskov substitution, Interface segregation, Dependency inversion."),
("Single responsibility principle", L, "A class should have one reason to change."),
("Open/closed principle", L, "Code should be open for extension but closed for modification."),
("Liskov substitution principle", L, "A subclass must be usable anywhere its parent is, without surprises."),
("Interface segregation principle", L, "Prefer several small interfaces to one large one."),
("Dependency inversion principle", L, "Depend on abstractions (interfaces), not concrete classes."),
("Design pattern", L, "A named, reusable solution to a common design problem."),
("Factory pattern", L, "A method or class that creates objects so callers don't need to know the exact class."),
("Builder pattern", L, "Builds complex objects step by step, avoiding long constructors."),
("Strategy pattern", L, "Swap algorithms at runtime behind a common interface."),
("Observer pattern", L, "Objects subscribe to events and get notified when something changes."),
("Decorator pattern", L, "Wraps an object to add behaviour without changing its class."),
("Adapter pattern", L, "Converts one interface into another that a client expects."),
("Low-level design (LLD)", L, "An interview round where you design classes, interfaces and their relationships for something like a parking lot."),
("Class diagram", L, "A drawing of classes, their fields and methods, and how they relate."),
# ---------- System design ----------
("System design interview", D, "A 45–60 minute round where you design a large system, focusing on requirements, components and trade-offs."),
("Functional requirements", D, "What the system must do, e.g. 'users can shorten a URL'."),
("Non-functional requirements", D, "How well it must do it: latency, availability, scale, consistency, cost."),
("Client-server", D, "A client sends requests; a server processes them and responds."),
("DNS", D, "Domain Name System: translates a name like amazon.com into an IP address."),
("IP address", D, "A numeric address that identifies a machine on a network."),
("HTTP / HTTPS", D, "The protocol browsers and services use to talk. HTTPS adds TLS encryption."),
("TLS", D, "Transport Layer Security: encrypts traffic between client and server."),
("Latency", D, "How long one request takes, usually in milliseconds."),
("Throughput", D, "How many requests a system handles per second."),
("p99 latency", D, "The latency that 99% of requests are faster than; shows the slow tail that averages hide."),
("Bandwidth", D, "How much data can move over a network per second."),
("Availability", D, "The share of time a system is up, e.g. 99.9% ('three nines') is about 8.8 hours of downtime a year."),
("SLA / SLO / SLI", D, "SLI: a measured metric. SLO: the internal target for it. SLA: a contractual promise to customers."),
("Reliability", D, "The system keeps working correctly even when parts fail."),
("Scalability", D, "Handling more load by adding resources."),
("Vertical scaling", D, "Scaling up: a bigger machine with more CPU and memory."),
("Horizontal scaling", D, "Scaling out: more machines sharing the load."),
("Stateless service", D, "A server that keeps no user data between requests, so any instance can handle any request."),
("Load balancer", D, "Spreads incoming requests across many servers."),
("L4 vs L7 load balancing", D, "L4 routes by IP and port (fast, e.g. AWS NLB); L7 routes by HTTP details like the path (e.g. AWS ALB)."),
("Health check", D, "A regular probe a load balancer or Kubernetes uses to decide if an instance can receive traffic."),
("Readiness / liveness probe", D, "Kubernetes checks: readiness says 'send me traffic'; liveness says 'restart me if I'm stuck'."),
("Reverse proxy", D, "A server in front of your services that forwards requests, e.g. Nginx or Envoy."),
("API gateway", D, "A single entry point for clients that handles routing, auth, rate limiting and more."),
("Cache", D, "Fast temporary storage (often in memory) for data that is read often."),
("Cache hit / miss", D, "Hit: the data was in the cache. Miss: it wasn't, so you go to the database."),
("Cache-aside", D, "The app checks the cache first, and on a miss loads from the database and fills the cache."),
("Write-through / write-back", D, "Write-through writes cache and DB together; write-back writes the cache first and the DB later."),
("TTL", D, "Time to live: how long a cached item stays before it expires."),
("Eviction policy", D, "How a full cache chooses what to remove, e.g. LRU (least recently used)."),
("Cache stampede", D, "Many requests miss the cache at once and overload the database."),
("Hot key", D, "A single key that gets a huge share of traffic and overloads one server."),
("Redis", D, "A popular in-memory key-value store used for caching, counters and queues."),
("CDN", D, "Content Delivery Network: servers around the world that cache content close to users."),
("SQL database", D, "A relational database with tables, joins and transactions, e.g. Postgres, Oracle, MySQL."),
("NoSQL database", D, "Non-relational stores (key-value, document, wide-column, graph) built for scale or flexible schemas."),
("Cassandra", D, "A wide-column NoSQL database built for high write throughput across many nodes."),
("ACID", D, "Atomicity, Consistency, Isolation, Durability: the guarantees of database transactions."),
("Index", D, "An extra data structure that makes lookups on a column fast, at the cost of slower writes and more storage."),
("B-tree / LSM tree", D, "B-trees (most SQL databases) are good for reads; LSM trees (Cassandra) are optimised for writes."),
("Replication", D, "Keeping copies of data on several machines for availability and read scaling."),
("Leader-follower", D, "One leader takes writes and followers copy them; followers can serve reads."),
("Replication lag", D, "The delay before a follower has the leader's latest writes."),
("Sharding / partitioning", D, "Splitting data across machines by a key so each holds only part of it."),
("Partition key", D, "The field that decides which shard or partition a record goes to."),
("Consistent hashing", D, "Places servers and keys on a ring so adding or removing a server moves only a few keys."),
("CAP theorem", D, "During a network partition, a distributed system must choose between consistency and availability."),
("Strong vs eventual consistency", D, "Strong: every read sees the latest write. Eventual: replicas catch up over time."),
("Quorum", D, "A majority of replicas that must agree for a read or write to succeed."),
("Message queue", D, "A buffer where producers put messages and consumers process them later, decoupling services."),
("Pub/sub", D, "Publish-subscribe: publishers send to a topic and every subscriber gets a copy."),
("Kafka", D, "A distributed log for streaming events, with topics, partitions and consumer groups."),
("Consumer group", D, "A set of Kafka consumers sharing a topic's partitions; each partition goes to one consumer in the group."),
("Offset", D, "A message's position in a Kafka partition; consumers commit offsets to track progress."),
("Kinesis", D, "AWS's managed streaming service, similar to Kafka."),
("Idempotency", D, "Doing an operation twice has the same effect as doing it once; essential for safe retries, e.g. payments."),
("At-least-once / exactly-once", D, "Delivery guarantees: at-least-once may duplicate messages; exactly-once processes each once."),
("Backpressure", D, "Slowing producers down when consumers can't keep up."),
("REST", D, "An API style using HTTP verbs (GET, POST, PUT, DELETE) on resources identified by URLs."),
("gRPC", D, "A fast binary RPC framework using Protocol Buffers, common between internal services."),
("Pagination", D, "Returning large result sets in pages, by offset or by cursor."),
("Rate limiting", D, "Capping how many requests a client can make per time window."),
("Token bucket", D, "A rate-limiting algorithm: tokens refill at a steady rate and each request spends one."),
("Back-of-the-envelope estimation", D, "Quick rough maths for traffic, storage and bandwidth to size a design."),
("QPS", D, "Queries per second: the request rate a system must handle."),
("Microservices", D, "An architecture of small, independently deployed services."),
("Monolith", D, "One application containing all features, deployed as a single unit."),
("Service discovery", D, "How services find each other's addresses dynamically."),
("Observability", D, "Understanding a system from its logs, metrics and traces."),
("Distributed tracing", D, "Following one request across many services with a shared trace ID."),
("Object storage", D, "Storage for files and blobs accessed by key, e.g. AWS S3."),
("Snowflake ID", D, "A 64-bit unique ID made from a timestamp, a machine ID and a sequence number; sortable by time."),
("Two-phase commit (2PC)", D, "A protocol to commit a transaction across multiple databases: prepare, then commit."),
("Saga", D, "A long transaction split into local steps, each with a compensating undo step."),
("Transactional outbox", D, "Writing an event to an 'outbox' table in the same DB transaction, then publishing it reliably."),
("Event sourcing", D, "Storing every change as an event and rebuilding current state by replaying them."),
("CQRS", D, "Command Query Responsibility Segregation: separate models for writes and reads."),
("WebSocket", D, "A persistent two-way connection between client and server for real-time updates."),
("Long polling / SSE", D, "Ways to push updates: long polling holds a request open; server-sent events stream one-way."),
("Leader election", D, "Choosing one node to coordinate work, e.g. with Raft or ZooKeeper."),
("Raft", D, "A consensus algorithm for keeping replicas in agreement through a leader."),
("Bloom filter", D, "A compact structure that says 'definitely not present' or 'maybe present', with no false negatives."),
("Inverted index", D, "A map from each word to the documents containing it; the basis of search engines."),
("Batch vs stream processing", D, "Batch processes large chunks on a schedule (Spark); streaming processes events as they arrive (Kafka, Kinesis)."),
("Authentication vs authorisation", D, "Authentication: who you are. Authorisation: what you're allowed to do."),
("Encryption at rest / in transit", D, "Protecting stored data, and data moving over the network."),
("RPO / RTO", D, "Recovery Point Objective: how much data you can lose. Recovery Time Objective: how fast you must recover."),
("Multi-region", D, "Running a system in several geographic regions for resilience and low latency."),
("Double-entry ledger", D, "Every money movement is recorded as a debit and an equal credit, so the books always balance."),
("Reconciliation", D, "Comparing two records of the same transactions to find mismatches."),
("Distributed lock", D, "A lock shared across machines, e.g. using Redis or ZooKeeper."),
("Geohash / quadtree", D, "Ways to index locations so 'find nearby' queries are fast."),
("Data warehouse / lake / lakehouse", D, "Warehouse: structured data for analytics. Lake: raw files of any kind. Lakehouse: both together (e.g. Databricks)."),
("Fan-out on write / read", D, "Push a new post to followers' feeds when it is written, or assemble feeds when they are read."),
("Heavy hitters", D, "The most frequent items in a huge stream, often found approximately."),
("Order book / matching engine", D, "The list of buy and sell orders on an exchange, and the system that matches them."),
# ---------- AI ----------
("AI (artificial intelligence)", A, "Software that performs tasks that normally need human intelligence."),
("Machine learning", A, "Systems that learn patterns from data instead of following hand-written rules."),
("LLM", A, "Large language model: an AI that generates text by predicting the next token, e.g. Claude, ChatGPT, Gemini."),
("Token", A, "A chunk of text (a word or part of one) that an LLM reads and writes; costs and limits are counted in tokens."),
("Next-token prediction", A, "How LLMs generate text: repeatedly predicting the most likely next token."),
("Context window", A, "The maximum amount of text (in tokens) an LLM can consider at once."),
("Temperature", A, "A setting that controls randomness: low gives focused, repeatable answers; high gives varied ones."),
("Prompt", A, "The instructions and context you give an AI model."),
("Prompt engineering", A, "Writing prompts that reliably get good results: role, context, constraints, examples."),
("System prompt", A, "Standing instructions that set the AI's role and rules for a whole conversation."),
("Few-shot prompting", A, "Including a few worked examples in the prompt to show the AI what you want."),
("Hallucination", A, "When an AI gives a confident answer that is wrong or made up."),
("Grounding", A, "Tying an AI's answer to trusted sources so it is less likely to make things up."),
("Embedding", A, "A list of numbers representing the meaning of text, so similar meanings are close together."),
("Vector database", A, "A database that stores embeddings and finds the most similar ones quickly."),
("Similarity search", A, "Finding items whose embeddings are closest to a query's embedding."),
("RAG", A, "Retrieval-augmented generation: fetch relevant documents first, then have the LLM answer using them."),
("Chunking", A, "Splitting documents into smaller pieces before embedding them for RAG."),
("Re-ranking", A, "A second pass that re-orders retrieved results to put the most relevant first."),
("Fine-tuning", A, "Further training a model on your own examples to change its behaviour or style."),
("Tool calling / function calling", A, "An LLM asking your code to run a function (e.g. a search or an API) and using the result."),
("AI agent", A, "An LLM that plans and takes multi-step actions using tools to reach a goal."),
("MCP", A, "Model Context Protocol: an open standard for connecting AI models to tools and data sources."),
("Evals", A, "Tests that measure how well an AI feature performs on a set of examples."),
("Structured output", A, "Getting an LLM to return data in a fixed format such as JSON."),
("Guardrails", A, "Rules and checks around an AI system that block unsafe or off-topic inputs and outputs."),
("Prompt injection", A, "An attack where hidden instructions in content trick an AI into doing something unintended."),
("Inference", A, "Running a trained model to get an output, as opposed to training it."),
("Latency (LLM)", A, "How long a model takes to respond, often split into time to first token and tokens per second."),
("Model routing", A, "Sending each request to the cheapest model that can handle it well, with fallbacks."),
("Prompt caching", A, "Reusing the processed beginning of a prompt across calls to cut cost and latency."),
("Copilot", A, "GitHub's AI coding assistant inside editors like VS Code."),
("AI coding agent", A, "A tool such as Claude Code or Cursor that can read a codebase, edit files and run commands."),
("AI-enabled coding round", A, "An interview round where you may use an AI assistant; it tests how you direct and verify the AI."),
("Code comprehension round", A, "Google's 2026 pilot round: read, debug and improve existing code, with Gemini available."),
("Amazon Bedrock", A, "AWS's managed service for using foundation models through an API."),
("Responsible AI", A, "Building AI that is fair, explainable, private and safe; heavily regulated in banking."),
# ---------- Interview ----------
("STAR method", I, "Situation, Task, Action, Result: a structure for behavioral answers."),
("Behavioral interview", I, "Questions about past experiences, e.g. 'Tell me about a time you disagreed with your manager'."),
("Leadership Principles", I, "Amazon's 16 principles (e.g. Customer Obsession, Ownership) used to score behavioral answers."),
("Googleyness", I, "Google's behavioral signal: collaboration, humility and comfort with ambiguity."),
("Bar raiser", I, "An experienced Amazon interviewer from another team who makes sure each hire raises the bar."),
("Phone screen", I, "An early 45–60 minute technical interview, usually one or two coding problems."),
("Onsite / virtual onsite", I, "The main loop of 4–6 interviews: coding, system design and behavioral."),
("Online assessment (OA)", I, "A timed coding test (e.g. on HackerRank) taken before interviews, common at banks and Amazon."),
("Hiring committee", I, "The group that reviews interview feedback and makes the hire decision (e.g. at Google)."),
("Levelling", I, "Deciding which level you're hired at (e.g. SDE2 vs senior); system design weighs heavily."),
("Down-levelling", I, "Being offered a lower level than your current title, common when moving from banks to big tech."),
("Mock interview", I, "A practice interview with a peer or a paid interviewer."),
("Mistake log", I, "A running list of mistakes and their fixes, reviewed before interviews."),
("Thinking aloud", I, "Narrating your reasoning while solving, so the interviewer can follow and help."),
("Clarifying questions", I, "Questions you ask at the start to pin down inputs, edge cases and requirements."),
("Trade-off", I, "What you gain and what you give up with a choice; interviewers expect you to name them."),
("Offer negotiation", I, "Discussing salary, bonus, stock and level after an offer; competing offers give leverage."),
]

def main():
    seen, out = set(), []
    for term, cat, meaning in T:
        k = term.lower()
        if k in seen: continue
        seen.add(k); out.append({"term": term, "category": cat, "meaning": meaning})
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    json.dump({"terms": out}, open(os.path.join(root, "data", "glossary.json"), "w"), indent=1, ensure_ascii=False)
    from collections import Counter
    print(len(out), Counter(t["category"] for t in out))

if __name__ == "__main__":
    main()
